AttachXFormValueChangeEventById("fd_mode", function(value) {
  SetXFormFieldValueById("fd_marker", value, false);
  if (value == "A") {
    common_dom_row_set_show_required_reset("row_primary", true, true, false);
    common_dom_row_set_show_required_reset("row_alias", true, true, false);
  } else {
    common_dom_row_set_show_required_reset("row_primary", false, false, false);
    common_dom_row_set_show_required_reset("row_alias", false, false, false);
  }
});
